fix.code:
@Service
class PaymentConfirmationService {
    private final OrderRepository orders;

    @Transactional
    void confirm(UUID orderId, PaymentReference reference) {
        Order order = orders.findById(orderId).orElseThrow();
        order.markPaid(reference);
        orders.save(order);   // cần gọi để Spring Data phát các domain event đã đăng ký
    }
}

@Component
class PaymentMailer {
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Async
    void on(OrderPaid event) { mail.sendReceipt(event.orderId()); }
}

